/*
 * A319838  Numbers k such that A319100(k) is a power of 6.
 * https://oeis.org/A319838
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   Numbers k such that * v(2,k)=0 or 1, * v(3,k)=0 or ≥2, * and k
 *            has no prime factor ≡ 5 (mod 6). * The sequence is generated by
 *            scanning the positive integers * in increasing order and keeping
 *            those that satisfy the above property
 * Range:     u8 n <= 62, u16 n <= 8928, u32 n <= 8928, u64 n <= 8928,
 *            u128 n <= 8928, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdint.h>
#include <stdlib.h>
#include <stdbool.h>
#include <stddef.h>

/* Forward declaration of seq_t and idx_t:
 * These types are defined by the build system. */

/* ------------------------------------------------------------------ */
/* Prime sieve (up to one million, enough for 10 000 terms)           */

static const uint32_t PRIME_SIEVE_LIMIT = 1000000U;
static uint32_t *primes = NULL;   /* array of primes */
static size_t   num_primes = 0;    /* number of primes */

static void init_primes(void)
{
    uint32_t limit = PRIME_SIEVE_LIMIT;
    bool *sieve = (bool*)calloc(limit + 1, sizeof(bool));
    if (!sieve) exit(EXIT_FAILURE);

    for (uint32_t i = 2; i * i <= limit; ++i) {
        if (!sieve[i]) {
            for (uint32_t j = i * i; j <= limit; j += i)
                sieve[j] = true;
        }
    }

    size_t count = 0;
    for (uint32_t i = 2; i <= limit; ++i)
        if (!sieve[i])
            ++count;

    primes = (uint32_t*)malloc(count * sizeof(uint32_t));
    if (!primes) exit(EXIT_FAILURE);

    size_t idx = 0;
    for (uint32_t i = 2; i <= limit; ++i)
        if (!sieve[i])
            primes[idx++] = i;

    num_primes = count;
    free(sieve);
}

/* ------------------------------------------------------------------ */
/* Helper: test whether a given integer satisfies the sequence rule */

static bool is_valid_k(uint64_t k)
{
    if (k == 0) return false;

    /* v(2,k) must be 0 or 1: reject if divisible by 4 */
    if ((k & 1ULL) == 0) {
        if ((k & 3ULL) == 0)   /* k % 4 == 0 */
            return false;
    }

    /* v(3,k) must be 0 or ≥2: reject if divisible by 3 but not by 9 */
    if (k % 3ULL == 0) {
        if (k % 9ULL != 0)
            return false;
    }

    /* Remove all 2’s and 3’s to test other prime factors */
    uint64_t m = k;
    while ((m & 1ULL) == 0)      /* all powers of 2 */
        m >>= 1;
    while (m % 3ULL == 0)        /* all powers of 3 */
        m /= 3ULL;

    /* Factor the remaining part: it must contain only primes ≡ 1 (mod 6) */
    uint64_t tmp = m;
    for (size_t i = 0; i < num_primes && (uint64_t)primes[i] * primes[i] <= tmp; ++i) {
        uint32_t p = primes[i];
        if (tmp % p == 0) {
            if (p % 6U == 5U) /* forbidden prime congruent to 5 mod 6 */
                return false;
            while (tmp % p == 0)
                tmp /= p;
        }
    }
    if (tmp > 1)                 /* remaining prime factor */
        if (tmp % 6ULL == 5ULL)
            return false;

    return true;
}

/* ------------------------------------------------------------------ */
/* Sequence generator                                                */

static seq_t *terms = NULL;        /* stored sequence values */
static size_t terms_len = 0;       /* number of terms stored */
static size_t terms_cap = 0;       /* capacity of the terms array */
static uint64_t next_k = 1;        /* next integer to test */
static bool seq_initialized = false;

seq_t a(idx_t n)
{
    if (!seq_initialized) {
        init_primes();
        seq_initialized = true;
    }

    /* Generate terms until we have at least n of them */
    while (terms_len < (size_t)n) {
        if (is_valid_k(next_k)) {
            if (terms_len == terms_cap) {
                size_t new_cap = terms_cap == 0 ? 16 : terms_cap * 2;
                seq_t *new_terms = (seq_t*)realloc(terms, new_cap * sizeof(seq_t));
                if (!new_terms) exit(EXIT_FAILURE);
                terms   = new_terms;
                terms_cap = new_cap;
            }
            terms[terms_len++] = (seq_t)next_k;
        }
        ++next_k;
    }
    return terms[n - 1];  /* sequence is 1‑based */
}
